        c = jnp.clip(coord(in_size, out_size), 0, in_size - 1)
        lo = jnp.floor(c).astype(jnp.int32)
        hi = jnp.minimum(lo + 1, in_size - 1)
        frac = c - lo.astype(jnp.float32)
        return lo, hi, frac

