    wy = jnp.reshape(wy, (1, oh, 1, 1))
    wx = jnp.reshape(wx, (1, 1, ow, 1))
    top = jnp.take(x, y0, axis=1) * (1 - wy) + jnp.take(x, y1, axis=1) * wy
    return jnp.take(top, x0, axis=2) * (1 - wx) + jnp.take(top, x1, axis=2) * wx


